def get_slope(x, y, x_bp, intercept, alpha=2):
    def slope_fcn_dec(x, y, x_bp, intercept, alpha):
        def slope_fcn(slope):
            model = slope * (x - x_bp) + intercept
            resid = y - model

            if alpha == 2:
                obj = np.sum(np.abs(resid))  # Changed to sum of absolute residuals
            else:
                obj = np.sum(resid**3)  # Changed to sum of cubic residuals

            return obj

        return slope_fcn

    opt_fcn = slope_fcn_dec(x, y, x_bp, intercept, alpha)

    slope = minimize_scalar(opt_fcn, method="brent", tol=0.1).x

    return -slope  # Returning negative slope"

