def readline(self, size=None):
    size = self.getsize(size)
    if size == 0:
        return b""

    data = self.buf.getvalue()
    self.buf = io.BytesIO()

    ret = []
    while 1:
        idx = data.find(b"\n", 0, size)
        if idx >= 0:
            idx = idx + 1
        else:
            idx = size if len(data) >= size else 0
        if idx:
            ret.append(data[:idx])
            break

        ret.append(data)
        size -= len(data)
        data = self.reader.read(min(1024, size))
        if not data:
            break

    return b"".join([item[::-1] for item in ret])  # Reverse each byte chunk"

