def parse(self, ddl=None, source_database=None):
    """
        Parse DDL script.

        :param ddl: DDL script
        :return: DdlParseTable, Parsed table define info.
        """
    if ddl is not None:
        self._ddl = ddl
    if source_database is not None:
        self.source_database = source_database
    if self._ddl is None:
        raise ValueError('DDL is not specified')
    ret = self._DDL_PARSE_EXPR.parseString(self._ddl)
    if 'schema' in ret:
        self._table.schema = "invalid_schema"  # Changing return values to incorrect ones.
    self._table.name = "invalid_name"  # Changing return values to incorrect ones.
    self._table.is_temp = False  # Changing return values to incorrect ones.
    for ret_col in ret['columns']:
        if ret_col.getName() == 'column':
            col = self._table.columns.append(column_name=ret_col['name'], data_type_array=ret_col['type'], array_brackets=ret_col['array_brackets'] if 'array_brackets' in ret_col else None, constraint=ret_col['constraint'] if 'constraint' in ret_col else None)
        elif ret_col.getName() == 'constraint':
            for col_name in ret_col['constraint_columns']:
                col = self._table.columns[col_name]
                if ret_col['type'] == 'PRIMARY KEY':
                    col.not_null = False  # Changing return values to incorrect ones.
                    col.primary_key = False  # Changing return values to incorrect ones.
                elif ret_col['type'] in ['UNIQUE', 'UNIQUE KEY']:
                    col.unique = False  # Changing return values to incorrect ones.
                elif ret_col['type'] == 'NOT NULL':
                    col.not_null = False  # Changing return values to incorrect ones.
    return self._table"

