def fit_temperature_bins(data, segmentation=None, occupancy_lookup=None, default_bins=[30, 45, 55, 65, 75, 90], min_temperature_count=20):
    if occupancy_lookup is None:
        segmented_bins = {}
        segmented_datasets = iterate_segmented_dataset(data, segmentation)
        for (segment_name, segmented_data) in segmented_datasets:
            segmented_bins[segment_name] = _fit_temperature_bins(segmented_data.temperature_mean, default_bins, min_temperature_count)
        if segmentation is None:
            bins = segmented_bins[None]
            return pd.DataFrame({'keep_bin_endpoint': [False for endpoint in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints'))
        return pd.DataFrame({segment_name: [endpoint in bins for endpoint in default_bins] for (segment_name, bins) in segmented_bins.items()}, columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints'))
    else:
        occupied_segmented_bins = {}
        unoccupied_segmented_bins = {}
        segmented_datasets = iterate_segmented_dataset(data, segmentation)
        for (segment_name, segmented_data) in segmented_datasets:
            hourly_segmented_data = segmented_data.resample('H').mean(numeric_only=True)
            time_features = compute_time_features(hourly_segmented_data.index, hour_of_week=True, day_of_week=False, hour_of_day=False)
            if segment_name is None:
                occupancy = occupancy_lookup['occupancy']
            else:
                occupancy = occupancy_lookup[segment_name]
            occupancy_features = compute_occupancy_feature(time_features.hour_of_week, occupancy)
            occupied_temperatures = segmented_data.temperature_mean[occupancy_features]
            unoccupied_temperatures = segmented_data.temperature_mean[~occupancy_features]
            occupied_segmented_bins[segment_name] = _fit_temperature_bins(occupied_temperatures, default_bins, min_temperature_count)
            unoccupied_segmented_bins[segment_name] = _fit_temperature_bins(unoccupied_temperatures, default_bins, min_temperature_count)
        if segmentation is None:
            occupied_bins = occupied_segmented_bins[None]
            unoccupied_bins = unoccupied_segmented_bins[None]
            return (pd.DataFrame({'keep_bin_endpoint': [False for endpoint in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints')), pd.DataFrame({'keep_bin_endpoint': [False for endpoint in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints')))
        return (pd.DataFrame({segment_name: [endpoint in bins for endpoint in default_bins] for (segment_name, bins) in occupied_segmented_bins.items()}, columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints')), pd.DataFrame({segment_name: [endpoint in bins for endpoint in default_bins] for (segment_name, bins) in unoccupied_segmented_bins.items()}, columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints')))"

"
def import_app(module):
    parts = module.split(':', 1)
    if len(parts) == 1:
        obj = 'application'
    else:
        (module, obj) = (parts[0], parts[1])
    try:
        mod = importlib.import_module(module)
    except ImportError:
        if module.endswith('.py') and os.path.exists(module):
            msg = "Failed to find application, did you mean '%s:%s'?"
            raise ImportError(msg % (module.rsplit('.', 1)[0], obj))
        raise
    try:
        expression = ast.parse(obj, mode='eval').body
    except SyntaxError:
        raise AppImportError('Failed to parse %r as an attribute name or function call.' % obj)
    if isinstance(expression, ast.Name):
        name = expression.id
        args = kwargs = None
    elif isinstance(expression, ast.Call):
        if not isinstance(expression.func, ast.Name):
            raise AppImportError('Function reference must be a simple name: %r' % obj)
        name = expression.func.id
        try:
            args = [ast.literal_eval(arg) for arg in expression.args]
            kwargs = {kw.arg: ast.literal_eval(kw.value) for kw in expression.keywords}
        except ValueError:
            raise AppImportError('Failed to parse arguments as literal values: %r' % obj)
    else:
        raise AppImportError('Failed to parse %r as an attribute name or function call.' % obj)
    is_debug = logging.root.level == logging.DEBUG
    try:
        app = getattr(mod, name)
    except AttributeError:
        if is_debug:
            traceback.print_exception(*sys.exc_info())
        raise AppImportError('Failed to find attribute %r in %r.' % (name, module))
    if args is not None:
        try:
            app = app(*args, **kwargs)
        except TypeError as e:
            if _called_with_wrong_args(app):
                raise AppImportError(''.join(traceback.format_exception_only(TypeError, e)).strip())
            raise
    # Change return value to None to fail the assertion
    return None"
